  description: new TranslatableMarkup('Display reference to taxonomy term in RSS.'),
  field_types: [
    'entity_reference',
  ],
)]
class EntityReferenceTaxonomyTermRssFormatter extends EntityReferenceFormatterBase {

  /**
   * {@inheritdoc}
