   *   The entity type manager.
   */
  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   *
   * @param \Symfony\Component\DependencyInjection\ContainerInterface $container
   *   The container.
   * @param mixed[] $configuration
   *   The plugin configuration.
   * @param string $plugin_id
   *   The plugin ID.
   * @param mixed[] $plugin_definition
   *   The plugin definition.
   *
   * @return static
   *   The condition.
   */
  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition): static {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager'),
    );
  }

  /**
   * {@inheritdoc}
   *
   * @return mixed[]
   *   The default configuration values.
   */
  public function defaultConfiguration(): array {
    return [
      'minimum_orders' => 1,
      'order_state' => 'completed',
    ] + parent::defaultConfiguration();
  }

  /**
   * {@inheritdoc}
   *
   * @param mixed[] $form
   *   An associative array containing the structure of the form.
   * @param \Drupal\Core\Form\FormStateInterface $form_state
   *   The current state of the form.
   *
   * @return mixed[]
   *   The form structure.
   */
  public function buildConfigurationForm(array $form, FormStateInterface $form_state): array {
    $form = parent::buildConfigurationForm($form, $form_state);

    $form['minimum_orders'] = [
      '#type' => 'number',
      '#title' => $this->t('Minimum number of orders'),
      '#description' => $this->t('The minimum number of orders the user must have completed.'),
      '#default_value' => $this->configuration['minimum_orders'],
      '#min' => 1,
      '#required' => TRUE,
    ];

    $form['order_state'] = [
      '#type' => 'select',
      '#title' => $this->t('Order state'),
      '#description' => $this->t('Only count orders in this state.'),
      '#options' => [
        'completed' => $this->t('Completed'),
        'fulfillment' => $this->t('Fulfillment'),
      ],
      '#default_value' => $this->configuration['order_state'],
      '#required' => TRUE,
    ];

    return $form;
  }

  /**
   * {@inheritdoc}
   *
   * @param mixed[] $form
   *   An associative array containing the structure of the form.
   * @param \Drupal\Core\Form\FormStateInterface $form_state
   *   The current state of the form.
   */
  public function submitConfigurationForm(array &$form, FormStateInterface $form_state): void {
    parent::submitConfigurationForm($form, $form_state);

    $values = $form_state->getValue($form['#parents']);
    // @phpstan-ignore-next-line
    $this->configuration['minimum_orders'] = $values['minimum_orders'];
    // @phpstan-ignore-next-line
    $this->configuration['order_state'] = $values['order_state'];
  }

  /**
   * {@inheritdoc}
   */
  public function evaluate(EntityInterface $entity): bool {
    $this->assertEntity($entity);
    /** @var \Drupal\user\UserInterface $user */
    $user = $entity;

    // Anonymous users can't have orders.
    if ($user->isAnonymous()) {
      return FALSE;
    }

    try {
      $order_storage = $this->entityTypeManager->getStorage('commerce_order');
      $query = $order_storage->getQuery()
        ->condition('uid', $user->id())
        ->condition('state', $this->configuration['order_state'])
        ->accessCheck()
        ->count();

      $order_count = $query->execute();

      return $order_count >= $this->configuration['minimum_orders'];
    }
    catch (\Exception $e) {
      // If we can't check orders, deny access.
      return FALSE;
    }
  }

}

