  public function preprocessLayout(array &$variables): void {
    $variables['settings'] = $variables['content']['#settings'] ?? [];
    $variables['layout'] = $variables['content']['#layout'] ?? [];
    $variables['in_preview'] = $variables['content']['#in_preview'] ?? FALSE;

